CREATE TABLE projects (id TEXT PRIMARY KEY, name TEXT NOT NULL, workspace_path TEXT CHECK (workspace_path IS NULL), next_task_number INTEGER NOT NULL DEFAULT 1 CHECK (next_task_number > 0), created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE tasks (id TEXT PRIMARY KEY, identifier TEXT NOT NULL UNIQUE, project_id TEXT NOT NULL REFERENCES projects(id), title TEXT NOT NULL, description TEXT NOT NULL DEFAULT '', status TEXT NOT NULL CHECK (status IN ('backlog', 'todo', 'in_progress', 'in_review', 'blocked', 'done', 'canceled')), priority TEXT NOT NULL CHECK (priority IN ('none', 'urgent', 'high', 'medium', 'low')), labels TEXT NOT NULL DEFAULT '[]', sort_order REAL NOT NULL, thread_id TEXT, creator_type TEXT NOT NULL CHECK (creator_type IN ('user', 'agent')), creator_id TEXT NOT NULL, creator_name TEXT NOT NULL, creator_avatar_url TEXT, assignee_type TEXT NOT NULL CHECK (assignee_type IN ('user', 'agent')), assignee_id TEXT NOT NULL, assignee_name TEXT NOT NULL, assignee_avatar_url TEXT, workflow_id TEXT, development_context_type TEXT CHECK (development_context_type IS NULL OR development_context_type IN ('branch', 'worktree')), development_branch TEXT, due_date TEXT, recurrence_interval INTEGER, recurrence_unit TEXT, archived_at TEXT, version INTEGER NOT NULL DEFAULT 1 CHECK (version > 0), created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE INDEX tasks_project_status_sort ON tasks(project_id, archived_at, status, sort_order, created_at);
CREATE TABLE task_relations (relation_type TEXT NOT NULL CHECK (relation_type IN ('parent', 'blocks', 'related')), source_task_id TEXT NOT NULL REFERENCES tasks(id) ON DELETE CASCADE, target_task_id TEXT NOT NULL REFERENCES tasks(id) ON DELETE CASCADE, created_at TEXT NOT NULL, CHECK (source_task_id <> target_task_id), CHECK (relation_type <> 'related' OR source_task_id < target_task_id), PRIMARY KEY (relation_type, source_task_id, target_task_id));
CREATE INDEX task_relations_target ON task_relations(relation_type, target_task_id);
CREATE UNIQUE INDEX task_relations_one_parent ON task_relations(target_task_id) WHERE relation_type = 'parent';
CREATE TRIGGER task_relations_prevent_parent_cycle BEFORE INSERT ON task_relations WHEN NEW.relation_type = 'parent' BEGIN SELECT RAISE(ABORT, 'RELATION_CYCLE') WHERE EXISTS (WITH RECURSIVE ancestors(id) AS (SELECT source_task_id FROM task_relations WHERE relation_type = 'parent' AND target_task_id = NEW.source_task_id UNION SELECT task_relations.source_task_id FROM task_relations JOIN ancestors ON task_relations.target_task_id = ancestors.id WHERE task_relations.relation_type = 'parent') SELECT 1 FROM ancestors WHERE id = NEW.target_task_id); END;
CREATE TABLE comments (id TEXT PRIMARY KEY, task_id TEXT NOT NULL REFERENCES tasks(id) ON DELETE CASCADE, body TEXT NOT NULL, thread_id TEXT, author_type TEXT NOT NULL CHECK (author_type IN ('user', 'agent')), author_id TEXT NOT NULL, author_name TEXT NOT NULL, author_avatar_url TEXT, version INTEGER NOT NULL DEFAULT 1 CHECK (version > 0), created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE INDEX comments_task_created ON comments(task_id, created_at, id);
CREATE TABLE attachments (id TEXT PRIMARY KEY, task_id TEXT NOT NULL REFERENCES tasks(id) ON DELETE CASCADE, comment_id TEXT REFERENCES comments(id) ON DELETE CASCADE, filename TEXT NOT NULL, content_type TEXT NOT NULL, size INTEGER NOT NULL CHECK (size >= 0), created_at TEXT NOT NULL);
CREATE INDEX attachments_task_created ON attachments(task_id, created_at, id);
CREATE INDEX attachments_comment_created ON attachments(comment_id, created_at, id);
CREATE TABLE workflow_workspaces (project_id TEXT PRIMARY KEY REFERENCES projects(id) ON DELETE CASCADE, workspace TEXT NOT NULL, version INTEGER NOT NULL DEFAULT 1 CHECK (version > 0), updated_at TEXT NOT NULL);
CREATE TABLE global_revision (singleton INTEGER PRIMARY KEY CHECK (singleton = 1), revision INTEGER NOT NULL DEFAULT 0 CHECK (revision >= 0));
INSERT INTO global_revision (singleton, revision) VALUES (1, 0);
CREATE TRIGGER projects_revision_insert AFTER INSERT ON projects BEGIN UPDATE global_revision SET revision = revision + 1 WHERE singleton = 1; END;
CREATE TRIGGER projects_revision_update AFTER UPDATE ON projects BEGIN UPDATE global_revision SET revision = revision + 1 WHERE singleton = 1; END;
CREATE TRIGGER projects_revision_delete AFTER DELETE ON projects BEGIN UPDATE global_revision SET revision = revision + 1 WHERE singleton = 1; END;
CREATE TRIGGER tasks_revision_insert AFTER INSERT ON tasks BEGIN UPDATE global_revision SET revision = revision + 1 WHERE singleton = 1; END;
CREATE TRIGGER tasks_revision_update AFTER UPDATE ON tasks BEGIN UPDATE global_revision SET revision = revision + 1 WHERE singleton = 1; END;
CREATE TRIGGER tasks_revision_delete AFTER DELETE ON tasks BEGIN UPDATE global_revision SET revision = revision + 1 WHERE singleton = 1; END;
CREATE TRIGGER task_relations_revision_insert AFTER INSERT ON task_relations BEGIN UPDATE global_revision SET revision = revision + 1 WHERE singleton = 1; END;
CREATE TRIGGER task_relations_revision_update AFTER UPDATE ON task_relations BEGIN UPDATE global_revision SET revision = revision + 1 WHERE singleton = 1; END;
CREATE TRIGGER task_relations_revision_delete AFTER DELETE ON task_relations BEGIN UPDATE global_revision SET revision = revision + 1 WHERE singleton = 1; END;
CREATE TRIGGER comments_revision_insert AFTER INSERT ON comments BEGIN UPDATE global_revision SET revision = revision + 1 WHERE singleton = 1; END;
CREATE TRIGGER comments_revision_update AFTER UPDATE ON comments BEGIN UPDATE global_revision SET revision = revision + 1 WHERE singleton = 1; END;
CREATE TRIGGER comments_revision_delete AFTER DELETE ON comments BEGIN UPDATE global_revision SET revision = revision + 1 WHERE singleton = 1; END;
CREATE TRIGGER attachments_revision_insert AFTER INSERT ON attachments BEGIN UPDATE global_revision SET revision = revision + 1 WHERE singleton = 1; END;
CREATE TRIGGER attachments_revision_update AFTER UPDATE ON attachments BEGIN UPDATE global_revision SET revision = revision + 1 WHERE singleton = 1; END;
CREATE TRIGGER attachments_revision_delete AFTER DELETE ON attachments BEGIN UPDATE global_revision SET revision = revision + 1 WHERE singleton = 1; END;
CREATE TRIGGER workflow_workspaces_revision_insert AFTER INSERT ON workflow_workspaces BEGIN UPDATE global_revision SET revision = revision + 1 WHERE singleton = 1; END;
CREATE TRIGGER workflow_workspaces_revision_update AFTER UPDATE ON workflow_workspaces BEGIN UPDATE global_revision SET revision = revision + 1 WHERE singleton = 1; END;
CREATE TRIGGER workflow_workspaces_revision_delete AFTER DELETE ON workflow_workspaces BEGIN UPDATE global_revision SET revision = revision + 1 WHERE singleton = 1; END;
